float new_step(float a, float b)
{
    if (a < b) return 1.;
    else return 0.;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord/iResolution.xy;

    float checkerNum = 5.;

    float c0 = new_step(mod(uv.x*checkerNum/2., 1.0), 0.5);
    float c1 = new_step(mod(uv.y*checkerNum/2., 1.0), 0.5);

    float c = 0.;

    if (c0 == c1) c = 1.;

    fragColor = vec4(c);
}
